%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;

% retrieve selected cuts used for further fitting
GH_FFCutsFits = recover_selected_cuts('GH_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

fit_res_field = 'all_fit_par';
separate_fig  = true; % if true, detach figures from live script
%%
% Plot S,J0,gamma as function of direction and incident energy
[S_op110,J_op110,G_op110,Sq_op110]= display_EiDep_blocks(GH_FFCutsFits, ... %[output:group:8414e72e] %[output:075c780b] %[output:5746f0e7] %[output:3c2cb3e7]
    'off110GHminFF',' <110> min FF change',fit_res_field,separate_fig); %[output:group:8414e72e] %[output:075c780b] %[output:5746f0e7] %[output:3c2cb3e7]
%
[S_op200,J_op200,G_op200,Sq_op200]= display_EiDep_blocks(GH_FFCutsFits, ... %[output:group:180598f6] %[output:553dfcf7] %[output:743d1bf0] %[output:3a044bba]
    'off200GHminFF',' <200> min FF change',fit_res_field,separate_fig); %[output:group:180598f6] %[output:553dfcf7] %[output:743d1bf0] %[output:3a044bba]
%
[S_md200,J_md200,G_md200,Sq_md200]= display_EiDep_blocks(GH_FFCutsFits, ... %[output:group:83e4122c] %[output:8d737593] %[output:336d193f] %[output:9753e579]
    'off200GHmidFF',' <200> medium FF change',fit_res_field,separate_fig); %[output:group:83e4122c] %[output:8d737593] %[output:336d193f] %[output:9753e579]
%
[S_ma110,J_ma110,G_ma110,Sq_ma110]= display_EiDep_blocks(GH_FFCutsFits, ... %[output:group:67761fd3] %[output:9d8e3ed7] %[output:819ece48] %[output:84c43c7a] %[output:69f57bb9] %[output:7acf4098] %[output:6ace6ea0] %[output:976b83b6]
    'off110GHmaxFF',' <110> max FF change',fit_res_field,separate_fig) %[output:group:67761fd3] %[output:9d8e3ed7] %[output:819ece48] %[output:84c43c7a] %[output:69f57bb9] %[output:7acf4098] %[output:6ace6ea0] %[output:976b83b6]
%
[S_ma200,J_ma200,G_ma200,Sq_ma200]= display_EiDep_blocks(GH_FFCutsFits, ... %[output:group:6b8ff8c7] %[output:345806e3] %[output:1c7ab8bf] %[output:7533ed7c]
    'off200GHmaxFF',' <200> max FF change',fit_res_field,separate_fig); %[output:group:6b8ff8c7] %[output:345806e3] %[output:1c7ab8bf] %[output:7533ed7c]

%%
% Plot S,J0,gamma as function of direction at given incident energy
plot_fp_var(separate_fig,'g', ... %[output:group:8aab8e40] %[output:1d7d823f] %[output:90319017]
    [S_op110(1),S_op200(1),S_md200(1),S_ma110(1),S_ma200(1)], ... %[output:1d7d823f] %[output:90319017]
    [J_op110(1),J_op200(1),J_md200(1),J_ma110(1),J_ma200(1)], ... %[output:1d7d823f] %[output:90319017]
    [G_op110(1),G_op200(1),G_md200(1),G_ma110(1),G_ma200(1)]) %[output:group:8aab8e40] %[output:1d7d823f] %[output:90319017]

plot_fp_var(separate_fig,'b', ...
    [S_op110(2),S_op200(2),S_md200(2),S_ma110(2),S_ma200(2)], ...
    [J_op110(2),J_op200(2),J_md200(2),J_ma110(2),J_ma200(2)], ...
    [G_op110(2),G_op200(2),G_md200(2),G_ma110(2),G_ma200(2)])

plot_fp_var(separate_fig,'r', ...
    [S_op110(3),S_op200(3),S_md200(3),S_ma110(3),S_ma200(3)], ...
    [J_op110(3),J_op200(3),J_md200(3),J_ma110(3),J_ma200(3)], ...
    [G_op110(3),G_op200(3),G_md200(3),G_ma110(3),G_ma200(3)])

%%
plot_fp_var(separate_fig,'g', {Sq_op110(1),'','',''});
plot_fp_var(separate_fig,'g', {'',Sq_op200(1),'',''});
plot_fp_var(separate_fig,'g', {'','',Sq_ma110(1),Sq_ma200(1)});

plot_fp_var(separate_fig,'b', {Sq_op110(2),'','',''});
plot_fp_var(separate_fig,'b', {'',Sq_op200(2),'',''});
plot_fp_var(separate_fig,'b', {'','',Sq_ma110(2),Sq_ma200(2)});

plot_fp_var(separate_fig,'r', {Sq_op110(3),'','',''});
plot_fp_var(separate_fig,'r', {'',Sq_op200(3),'',''});
plot_fp_var(separate_fig,'r', {'','',Sq_ma110(3),Sq_ma200(1)});




